request_response_constraints.verification_script:
def verify_latest_response(latest_response, request_info):
    try:
        limit_param = request_info.get('limit')
        if limit_param is None:
            return 0
        limit_resp = latest_response.get('limit')
        if limit_resp is None:
            return 0
        if int(limit_resp) == int(limit_param):
            return 1
        return -1
    except:
        return 0

def verify_latest_response(latest_response, request_info):
    try:
        offset_param = request_info.get('offset')
        if offset_param is None:
            return 0
        offset_resp = latest_response.get('offset')
        if offset_resp is None:
            return 0
        if int(offset_resp) == int(offset_param):
            return 1
        return -1
    except:
        return 0

def verify_latest_response(latest_response, request_info):
    try:
        market_param = request_info.get('market')
        if market_param is None:
            return 0
        items = latest_response.get('items')
        if not items:
            return 0
        checked = False
        for item in items:
            # If is_playable is present, track relinking is applied - indeterminate
            if 'is_playable' in item:
                return 0
            markets = item.get('available_markets')
            if markets is None:
                continue
            checked = True
            if market_param not in markets:
                return -1
        return 1 if checked else 0
    except:
        return 0
